rows = re.findall(r'"'^'"\\| \\[["'^'"\\]]+\\]\\(#(["'^'"\\)]+)\\) \\| "'`(GET|POST)` '"\\| "'`([''^'"\\x60]+)"'` '"\\| (修改|新增) \\| "'`(breaking|compatible)` '"\\|"'$'"', document, re.M)
assert set(targets) == set(links) == {row[0] for row in rows}
assert len(targets) == len(rows) == 3
assert set(links).issubset(set(targets))
assert all(line == line.rstrip() for line in document.splitlines())
assert document.endswith(\"\\n\")

def execute(operation, payload=None, args=(), authenticated=True):
    flask.request.payload = payload
    flask.request.headers = {\"X-User-Id\": \"test\"} if authenticated else {}
    return operation(*args)

