for _, method, path, change, verdict in rows:
    route = method, path.replace(\"{orderId}\", \"<order_id>\")
    assert route in app.routes
    relative = method, route[1].removeprefix(\"/api/v1/orders\")
    assert (relative in baseline.bp.routes) == (change == \"修改\")
    args = (\"O111111111111\",) if \"<order_id>\" in route[1] else ()
    error(execute(app.routes[route], args=args, authenticated=False), 401, 40100, \"unauthorized\")
assert set(orders.bp.routes) - set(baseline.bp.routes) == {(\"GET\", \"/<order_id>/logistics\")}

request_example, create_example, logistics_example = [
    json.loads(body) for body in re.findall(r'"'```json'"\\n(.*?)\\n"'```'"', document, re.S)
]
assert execute(orders.create_order, request_example) == create_example
order_id = create_example[\"data\"][\"orderId\"]
assert execute(orders.logistics, args=(order_id,)) == logistics_example
assert execute(orders.logistics, args=(\"other-id\",))[\"data\"][\"orderId\"] == \"other-id\"
assert success(execute(orders.get_order, args=(order_id,))) == {
    \"orderId\": order_id, \"status\": \"CREATED\", \"items\": [], \"note\": \"\"
}
assert \"remark\" in success(execute(baseline.get_order, args=(order_id,)))
error(execute(orders.get_order, args=(\"bad\",)), 404, 40400, \"order not found\")

def order(qty, **fields):
    return {\"items\": [{\"skuId\": \"SKU-123\", \"qty\": qty}], **fields}

