error(execute(orders.create_order, order(100)), 400, 40002, \"invalid item\")
for qty in (1, 99):
    assert success(execute(orders.create_order, order(qty)))[\"items\"][0][\"qty\"] == qty
for qty in (0, -1):
    error(execute(orders.create_order, order(qty)), 400, 40002, \"invalid item\")
for payload in (None, {}, {\"items\": None}, {\"items\": []}):
    error(execute(orders.create_order, payload), 400, 40001, \"items required\")
for item in ({}, {\"skuId\": \"SKU-123\"}, {\"qty\": 1}, {\"skuId\": \"\", \"qty\": 1}):
    error(execute(orders.create_order, {\"items\": [item]}), 400, 40002, \"invalid item\")
for qty in (None, \"invalid\"):
    try:
        execute(orders.create_order, order(qty))
    except (TypeError, ValueError):
        pass
    else:
        raise AssertionError(qty)
assert success(execute(baseline.create_order, order(2, remark=\"前台\")))[\"remark\"] == \"前台\"
payload = success(execute(orders.create_order, order(2, remark=\"前台\")))
assert \"remark\" not in payload and payload[\"note\"] == \"\"
payload = success(execute(orders.create_order, order(2, note=None, couponCode=\"\")))
assert payload[\"note\"] is None and payload[\"couponCode\"] == \"\"
assert success(execute(orders.create_order, order(2, note=\"前台\", remark=\"旧值\")))[\"note\"] == \"前台\"
print(\"Verified 3 operation links and declared routes, 3 JSON examples, and main/HEAD handler behavior (Flask shim).\")
